-- ============================================================
-- SEAT_CLASS — 3 classes per aircraft (54 rows total)
-- The trigger trg_auto_generate_seats will auto-populate
-- SEAT_INVENTORY for each row inserted here.
-- Seat counts vary by aircraft type:
--   B787-9 / B787-10 / A350: First 2, Business 4, Economy 18
--   B777-300ER:              First 2, Business 6, Economy 24
--   A380-800 / B747-8:       First 4, Business 8, Economy 30
-- ============================================================

-- For each aircraft, insert three seat classes using a CTE-like approach.
-- Pricing reflects rough real-world fare bands per class per aircraft type.

-- A380-800 / 747-8 (largest aircraft → highest capacity, premium pricing)
INSERT INTO public."SEAT_CLASS" (class_name, aircraft_id, seat_count, price)
SELECT 'First',    ac.aircraft_id, 4,  2200.00
FROM public."AIRCRAFT" ac
WHERE ac.model IN ('Airbus A380-800', 'Boeing 747-8')
ON CONFLICT (aircraft_id, class_name) DO NOTHING;

INSERT INTO public."SEAT_CLASS" (class_name, aircraft_id, seat_count, price)
