-- ============================================================
-- STOPOVER (7 rows: 5 single-stop schedules + 1 two-stop schedule)
-- ============================================================

-- EK350: DXB stop, arrives +10h, departs +12h
INSERT INTO public."STOPOVER" (schedule_id, airport_iata, arrival_time_offset, departure_time_offset, stop_order)
SELECT schedule_id, 'DXB', interval '10 hours', interval '12 hours', 1
FROM public."FLIGHT_SCHEDULE" WHERE flight_number = 'EK350'
ON CONFLICT (schedule_id, stop_order) DO NOTHING;

-- QR858: DOH stop
INSERT INTO public."STOPOVER" (schedule_id, airport_iata, arrival_time_offset, departure_time_offset, stop_order)
SELECT schedule_id, 'DOH', interval '7 hours', interval '9 hours', 1
FROM public."FLIGHT_SCHEDULE" WHERE flight_number = 'QR858'
ON CONFLICT (schedule_id, stop_order) DO NOTHING;

-- LH716: FRA stop
INSERT INTO public."STOPOVER" (schedule_id, airport_iata, arrival_time_offset, departure_time_offset, stop_order)
SELECT schedule_id, 'FRA', interval '13 hours', interval '15 hours', 1
FROM public."FLIGHT_SCHEDULE" WHERE flight_number = 'LH716'
ON CONFLICT (schedule_id, stop_order) DO NOTHING;

-- SQ12: NRT stop
